  createdAt?: string
}

type NewPostInput = {
  title?: string
  content?: string
}

export function GET(): NextResponse<Post[]> {
  const posts: Post[] = [
    { id: 1, title: 'First Post', content: 'This is the first post' },
    { id: 2, title: 'Second Post', content: 'This is the second post' },
  ]

  return NextResponse.json(posts, { status: 200 })
}

export async function POST(request: Request): Promise<NextResponse> {
  const body = (await request.json().catch(() => ({}))) as NewPostInput
  const { title, content } = body

  if (!title || !content) {
    return NextResponse.json(
      { error: 'Title and content are required' },
      { status: 400 }
    )
  }

  const newPost: Post = {
    id: Date.now(),
    title,
    content,
    createdAt: new Date().toISOString(),
  }

  return NextResponse.json(newPost, { status: 201 })
}

import { NextResponse } from 'next/server'

export const dynamic = 'force-dynamic'

type Post = {
  id: number
  title: string
  content: string
  createdAt?: string
  updatedAt?: string
}

type UpdatePostInput = {
  title?: string
  content?: string
}

type RouteContext = {
  params: Promise<{ id: string }>
}

export async function GET(
  _request: Request,
  { params }: RouteContext
): Promise<NextResponse<Post>> {
  const { id } = await params
  const post: Post = {
    id: parseInt(id, 10),
    title: `Post ${id}`,
    content: `This is the content for post ${id}`,
    createdAt: new Date().toISOString(),
  }

  return NextResponse.json(post, { status: 200 })
}

export async function PUT(
  request: Request,
  { params }: RouteContext
): Promise<NextResponse<Post>> {
  const { id } = await params
  const body = (await request.json().catch(() => ({}))) as UpdatePostInput
  const { title, content } = body

  const updatedPost: Post = {
    id: parseInt(id, 10),
    title: title || `Post ${id}`,
    content: content || `Updated content for post ${id}`,
    updatedAt: new Date().toISOString(),
  }

  return NextResponse.json(updatedPost, { status: 200 })
}

export async function DELETE(
  _request: Request,
  { params }: RouteContext
): Promise<NextResponse<{ message: string }>> {
  const { id } = await params
  return NextResponse.json(
    { message: `Post ${id} deleted successfully` },
    { status: 200 }
  )
}

